16		id       os.FileInfo // from the open handle's Stat at the last read; nil before
17		offset   int64       // just past the last complete line folded in
18		size     int64       // file size at the last read
19		modTime  time.Time   // Lstat mtime at the last listing
20		skipFrom int64       // start of an oversized line still being written, or -1
21		tail     bool        // an incomplete line follows offset (TruncatedFiles)
22		issue    IssueKind   // state issue of the last read (D6), valid if hasIssue
23		issueOff int64
24		hasIssue bool
25	}
26	
27	// newFileCursor returns the cursor of a transcript not read yet.
28	func newFileCursor(path, name, agent, rank string) fileCursor {
29		return fileCursor{path: path, name: name, agent: agent, rank: rank, skipFrom: -1}
30	}
31	
32	// transcriptFile is what readFile needs from an open transcript; *os.File
33	// satisfies it.
34	type transcriptFile interface {
35		io.Reader
36		io.ReaderAt
37		io.Seeker
38		io.Closer
39		Stat() (os.FileInfo, error)
40	}
41	
42	// openTranscript opens a transcript through openPlain. A var so tests can
43	// count opens and bytes read.
44	var openTranscript = func(path string) (transcriptFile, error) {
45		f, err := openPlain(path, false)
46		if err != nil {
47			return nil, err
48		}
49		if f == nil {
50			return nil, errNotRegular
51		}
52		return f, nil
53	}
54	
55	// fileRead is the outcome of reading one file from its cursor.
56	type fileRead struct {
57		next  fileCursor
58		part  *table // lines folded from the new bytes; nil when nothing was read
59		reset bool   // not an append (D4): the caller restarts the whole session
60	}
61	
62	// read reports whether the cursor has already read part of its file.
63	func (fc fileCursor) read() bool { return fc.offset > 0 || fc.skipFrom >= 0 || fc.id != nil }
64	
65	// quiet reports whether the file is, as far as Lstat can tell, exactly what the
66	// last read saw. A cursor holding a read error never is: the bytes between
67	// its offset and the failure must be read again.
68	func (fc fileCursor) quiet(li os.FileInfo) bool {
69		if fc.id == nil || (fc.hasIssue && fc.issue == IssueReadError) {
70			return false
71		}
72		return li.Size() == fc.size && os.SameFile(li, fc.id)
73	}
74	
75	// failRead is the outcome of a path that cannot be read: a reset when the file
76	// was read before (D4), else a state issue cleared by the next success (D6).
77	func failRead(fc fileCursor) fileRead {
78		if fc.read() {
79			return fileRead{next: fc, reset: true}
80		}
81		fc.issue, fc.issueOff, fc.hasIssue = IssueOpenFailed, 0, true
82		return fileRead{next: fc}
83	}
84	
85	// isAppend reports whether the open file is the one fc read, only grown (D4).
86	func (fc fileCursor) isAppend(f transcriptFile, fi os.FileInfo) bool {
87		if (fc.id != nil && !os.SameFile(fi, fc.id)) || fi.Size() < fc.size {
88			return false
89		}
90		if fc.offset == 0 {
91			return true
92		}
93		var b [1]byte
94		n, _ := f.ReadAt(b[:], fc.offset-1)
95		return n == 1 && b[0] == '\n'
96	}
97	
98	// readFile reads what was appended to fc's file since fc. now clamps mtimes.
99	// It never follows a link and never opens a non-regular file.
100	func readFile(fc fileCursor, now time.Time) fileRead {
101		li, err := os.Lstat(fc.path)
102		if err != nil || !li.Mode().IsRegular() {
103			return failRead(fc)
104		}
105		fc.modTime = li.ModTime()
106		if fc.modTime.After(now) {
107			fc.modTime = now
108		}
109		if fc.quiet(li) {
110			return fileRead{next: fc}
111		}
112		f, err := openTranscript(fc.path)
113		if err != nil {
114			return failRead(fc)
115		}
116		defer func() { _ = f.Close() }()
117		fi, err := f.Stat()
118		if err != nil {
119			return failRead(fc)
120		}
121		if !fc.isAppend(f, fi) {
122			return fileRead{next: fc, reset: true}
123		}
124		return fc.scan(f, fi)
125	}
126	
127	// scan folds the lines past the cursor into a new table and returns the
128	// advanced cursor. A line held back is read again next time (D1); an
129	// oversized one still being written is resumed in skip mode (D2).
130	func (fc fileCursor) scan(f transcriptFile, fi os.FileInfo) fileRead {
131		start := fc.offset
132		if fc.skipFrom >= 0 {
133			start = fc.size
134		}
135		if _, err := f.Seek(start, io.SeekStart); err != nil {
136			return failRead(fc)
137		}
138		part := newTable()
139		res, err := scanFrom(f, start, fc.skipFrom, MaxLineBytes, func(line []byte, off int64) {
140			part.addLine(fc.agent, fc.name, pos{rank: fc.rank, off: off}, line)
141		})
142		for _, off := range res.OversizedAt {
143			part.addOversized(fc.name, pos{rank: fc.rank, off: off})
144		}
145		next := fc
146		next.id, next.size, next.skipFrom = fi, res.End, res.SkipFrom
147		next.offset, next.tail = res.Consumed, len(res.Tail) > 0
148		if fc.skipFrom >= 0 && res.Consumed == start {
149			next.offset = fc.offset // the oversized line has not ended yet
150		}
151		next.issue, next.issueOff, next.hasIssue = 0, 0, false
152		if err != nil {
153			next.issue, next.issueOff, next.hasIssue = IssueReadError, next.offset, true
154		}
155		return fileRead{next: next, part: part}
156	}
