1	package agentusage
2	
3	import (
4		"io"
5		"path/filepath"
6		"sort"
7	)
8	
9	// ParseSession aggregates the usage of every agent of a session. It fails
10	// only if the parent transcript cannot be opened; a sub-agent that cannot be
11	// read stays in Agents with no tokens and a FileIssue.
12	func ParseSession(files SessionFiles) (Usage, error) {
13		subs := append([]SubAgentFiles(nil), files.SubAgents...)
14		sort.Slice(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
15		t := newTable()
16		agents := []Agent{{Main: true, State: StateUnknown}}
17		var meta Diagnostics // MetaMissing and MetaUnreadable
18		var truncated []string
19		parentName := sanitizeLabel(filepath.Base(files.Parent))
20		tail, err := parseFile(t, "", parentName, parentRank, files.Parent)
21		if err != nil {
22			return Usage{}, baseOnly(err)
23		}
24		if tail {
25			truncated = append(truncated, parentName)
26		}
27		for _, sa := range subs {
28			ag := agentFromMeta(&meta, sa)
29			name := sanitizeLabel(filepath.Base(sa.Transcript))
30			rank := transcriptRank(ag.ID, name, sa.ID, sa.Transcript)
31			ag.key = rank
32			agents = append(agents, ag)
33			tail, err := parseFile(t, rank, name, rank, sa.Transcript)
34			if err != nil {
35				t.addFileIssue(name, pos{rank: rank}, IssueOpenFailed)
36			}
37			if tail {
38				truncated = append(truncated, name)
39			}
40		}
41		agents, diag, versions := t.finish(agents)
42		diag.MetaMissing, diag.MetaUnreadable, diag.TruncatedFiles = meta.MetaMissing, meta.MetaUnreadable, truncated
43		return Usage{
44			SessionID:   sanitizeLabel(files.ID),
45			Agents:      agents,
46			Versions:    versions,
47			Diagnostics: diag,
48		}, nil
49	}
50	
51	// agentFromMeta builds a sub-agent's identity from its meta file, counting
52	// a missing or unreadable one in diag.
53	func agentFromMeta(diag *Diagnostics, sa SubAgentFiles) Agent {
54		ag := Agent{ID: sanitizeLabel(sa.ID)}
55		if sa.Meta == "" {
56			diag.MetaMissing++
57			return ag
58		}
59		m, err := readMeta(sa.Meta)
60		if err != nil {
61			diag.MetaUnreadable++
62			return ag
63		}
64		ag.Type, ag.State, ag.SpawnDepth = m.AgentType, m.state(), m.SpawnDepth
65		return ag
66	}
67	
68	// parseFile folds one transcript into the table for agent ("" for the
69	// parent) and reports whether it ends with an incomplete line. It fails only
70	// if the file cannot be opened.
71	func parseFile(t *table, agent, name, rank, path string) (bool, error) {
72		f, err := openPlain(path, false)
73		if err != nil {
74			return false, err
75		}
76		if f == nil {
77			return false, errNotRegular
78		}
79		defer func() { _ = f.Close() }()
80		return parseReader(t, agent, name, rank, f), nil
81	}
82	
83	// parseReader folds r into t for agent; name is the file's sanitized base
84	// name and rank its position rank. It reports whether r ends with an
85	// incomplete line. A read error mid-stream keeps what was read and is
86	// recorded as an IssueReadError at the offset consumed; it is not an
87	// unreadable line.
88	func parseReader(t *table, agent, name, rank string, r io.Reader) bool {
89		res, err := scanLines(r, MaxLineBytes, func(line []byte, off int64) {
90			t.addLine(agent, name, pos{rank: rank, off: off}, line)
91		})
92		for _, off := range res.OversizedAt {
93			t.addOversized(name, pos{rank: rank, off: off})
94		}
95		if err != nil {
96			t.addFileIssue(name, pos{rank: rank, off: res.Consumed}, IssueReadError)
97		}
98		return len(res.Tail) > 0
99	}
