49	// swapOpen replaces openTranscript for the length of the test.
50	func swapOpen(t *testing.T, fn func(path string) (transcriptFile, error)) {
51		t.Helper()
52		orig := openTranscript
53		openTranscript = fn
54		t.Cleanup(func() { openTranscript = orig })
55	}
56	
57	// countOpens counts opens and bytes read by readFile.
58	func countOpens(t *testing.T) *probe {
59		t.Helper()
60		p := &probe{}
61		orig := openTranscript
62		swapOpen(t, func(path string) (transcriptFile, error) {
63			f, err := orig(path)
64			if err != nil {
65				return nil, err
66			}
67			p.opens++
68			return countingFile{f, p}, nil
69		})
70		return p
71	}
72	
73	var errFault = errors.New("injected read failure")
74	
75	// faultyFile fails with errFault once limit bytes were delivered through Read.
76	type faultyFile struct {
77		transcriptFile
78		limit, n int64
79	}
80	
81	func (f *faultyFile) Read(b []byte) (int, error) {
82		if f.n >= f.limit {
83			return 0, errFault
84		}
85		if rem := f.limit - f.n; int64(len(b)) > rem {
86			b = b[:rem]
87		}
88		n, err := f.transcriptFile.Read(b)
89		f.n += int64(n)
90		return n, err
91	}
92	
93	// faultFirstOpen makes the first open fail after limit bytes; later opens
94	// are normal. It returns a counter of opens.
95	func faultFirstOpen(t *testing.T, limit int64) *probe {
96		t.Helper()
97		p := &probe{}
98		orig := openTranscript
99		swapOpen(t, func(path string) (transcriptFile, error) {
100			f, err := orig(path)
101			if err != nil {
102				return nil, err
103			}
104			p.opens++
105			if p.opens == 1 {
106				return &faultyFile{transcriptFile: f, limit: limit}, nil
107			}
108			return f, nil
109		})
110		return p
111	}
