427		fold(all, fr1.part)
428		if fr1.next.skipFrom != int64(len(a)) {
429			t.Fatalf("skipFrom = %d, want %d", fr1.next.skipFrom, len(a))
430		}
431		if fr1.part == nil || fr1.part.oversized != 0 || fr1.next.tail {
432			t.Fatalf("in-progress line must be neither counted nor a tail: part=%+v tail=%v", fr1.part, fr1.next.tail)
433		}
434		if fr1.next.offset != int64(len(a)) {
435			t.Fatalf("offset = %d, want %d (just past the last complete line)", fr1.next.offset, len(a))
436		}
437	
438		more := bytes.Repeat([]byte("x"), 100)
439		appendFile(t, path, more)
440		*p = probe{}
441		fr2 := step(t, fr1.next)
442		fold(all, fr2.part)
443		if limit := int64(len(more)) + 1; p.bytes > limit {
444			t.Errorf("resume consumed %d bytes, want <= %d (only the new ones)", p.bytes, limit)
445		}
446		if fr2.next.skipFrom != int64(len(a)) || (fr2.part != nil && fr2.part.oversized != 0) {
447			t.Errorf("still unfinished: skipFrom=%d part=%+v", fr2.next.skipFrom, fr2.part)
448		}
449	
450		appendFile(t, path, cat([]byte("\n"), ln("b")))
451		fr3 := step(t, fr2.next)
452		fold(all, fr3.part)
453		if fr3.part == nil || fr3.part.oversized != 1 {
454			t.Fatalf("ended line: part = %+v, want one oversized", fr3.part)
455		}
456		if fr3.next.skipFrom != -1 || fr3.next.tail {
457			t.Errorf("skipFrom=%d tail=%v after the line ended, want -1 and false", fr3.next.skipFrom, fr3.next.tail)
458		}
459		_, diag, _ := all.finish([]Agent{{Main: true}})
460		if len(diag.Files) != 1 || diag.Files[0].Offset != int64(len(a)) {
461			t.Errorf("Files = %+v, want one oversized at its start %d", diag.Files, len(a))
462		}
463		assertMatchesParseSession(t, path, all)
464	}
465	
466	// --- not an append: reset (D4) ------------------------------------------
467	
468	func TestReadFileNotAnAppendResets(t *testing.T) {
469		isolateReadFileHome(t)
470		initial := cat(ln("a"), ln("b"), ln("c"))
471		tests := []struct {
472			name   string
473			mutate func(t *testing.T, path string)
474		}{
475			{"truncated shorter", func(t *testing.T, path string) { putFile(t, path, ln("a")) }},
476			{"truncated then regrown past the offset", func(t *testing.T, path string) {
477				putFile(t, path, bytes.Repeat([]byte("x"), 2*len(initial)))
478			}},
479			{"rotated, same size", func(t *testing.T, path string) {
480				other := strings.NewReplacer(`"id":"a"`, `"id":"x"`, `"id":"b"`, `"id":"y"`, `"id":"c"`, `"id":"z"`).Replace(string(initial))
481				if len(other) != len(initial) {
482					t.Fatal("setup: replacement changed the size")
483				}
484				tmp := path + ".new"
485				putFile(t, tmp, []byte(other))
486				if err := os.Rename(tmp, path); err != nil {
487					t.Fatal(err)
488				}
489			}},
490			{"rotated, larger", func(t *testing.T, path string) {
491				tmp := path + ".new"
492				putFile(t, tmp, cat(initial, ln("d")))
493				if err := os.Rename(tmp, path); err != nil {
494					t.Fatal(err)
495				}
496			}},
497			{"deleted", func(t *testing.T, path string) {
498				if err := os.Remove(path); err != nil {
499					t.Fatal(err)
500				}
501			}},
502			{"replaced by a link, same content", func(t *testing.T, path string) {
503				target := path + ".target"
504				putFile(t, target, initial)
505				if err := os.Remove(path); err != nil {
506					t.Fatal(err)
507				}
508				if err := os.Symlink(target, path); err != nil {
509					t.Skipf("symlinks unavailable: %v", err)
510				}
511			}},
512			{"appended but no longer openable", func(t *testing.T, path string) {
513				appendFile(t, path, ln("d"))
514				swapOpen(t, func(string) (transcriptFile, error) { return nil, os.ErrPermission })
515			}},
516		}
517		for _, tc := range tests {
518			t.Run(tc.name, func(t *testing.T) {
519				path := filepath.Join(t.TempDir(), "p.jsonl")
520				putFile(t, path, initial)
521				fr1 := step(t, cur(path))
522				if fr1.next.id == nil || fr1.next.offset != int64(len(initial)) {
523					t.Fatalf("setup: id nil=%v offset=%d", fr1.next.id == nil, fr1.next.offset)
524				}
525				tc.mutate(t, path)
526				if fr2 := pass(fr1.next); !fr2.reset {
527					t.Errorf("reset = false, want true (part %v)", partIDs(fr2.part))
528				}
529			})
530		}
531	}
