578	// --- D6: errors are states, cleared by a later success --------------------
579	
580	func TestReadFileOpenFailureClearsOnALaterSuccess(t *testing.T) {
581		isolateReadFileHome(t)
582		path := filepath.Join(t.TempDir(), "p.jsonl")
583		fr1 := step(t, cur(path))
584		if !fr1.next.hasIssue || fr1.next.issue != IssueOpenFailed {
585			t.Fatalf("missing file: issue = %v (has %v)", fr1.next.issue, fr1.next.hasIssue)
586		}
587		putFile(t, path, cat(ln("a"), ln("b")))
588		fr2 := step(t, fr1.next)
589		if fr2.next.hasIssue {
590			t.Errorf("issue %v still set after a successful read", fr2.next.issue)
591		}
592		if got := partIDs(fr2.part); !reflect.DeepEqual(got, []string{"a", "b"}) {
593			t.Errorf("ids = %v, want [a b]", got)
594		}
595	}
596	
597	func TestReadFileOpenErrorOnAFreshCursorIsAStateThenClears(t *testing.T) {
598		isolateReadFileHome(t)
599		path := filepath.Join(t.TempDir(), "p.jsonl")
600		putFile(t, path, ln("a"))
601		orig := openTranscript
602		swapOpen(t, func(string) (transcriptFile, error) { return nil, os.ErrPermission })
603	
604		fr1 := pass(cur(path))
605		if fr1.reset || !fr1.next.hasIssue || fr1.next.issue != IssueOpenFailed {
606			t.Fatalf("reset=%v issue=%v (has %v), want a state IssueOpenFailed", fr1.reset, fr1.next.issue, fr1.next.hasIssue)
607		}
608		openTranscript = orig
609		fr2 := step(t, fr1.next)
610		if fr2.next.hasIssue || !reflect.DeepEqual(partIDs(fr2.part), []string{"a"}) {
611			t.Errorf("after recovery: issue=%v ids=%v", fr2.next.hasIssue, partIDs(fr2.part))
612		}
613	}
