137	}
138	
139	func cat(parts ...[]byte) []byte { return bytes.Join(parts, nil) }
140	
141	// cur is the cursor of a parent transcript not read yet.
142	func cur(path string) fileCursor {
143		return newFileCursor(path, sanitizeLabel(filepath.Base(path)), "", parentRank)
144	}
145	
146	func pass(fc fileCursor) fileRead { return readFile(fc, time.Now()) }
147	
148	// step reads once and fails if the read asks for a reset.
149	func step(t *testing.T, fc fileCursor) fileRead {
150		t.Helper()
151		fr := pass(fc)
152		if fr.reset {
153			t.Fatal("unexpected reset")
154		}
155		return fr
156	}
157	
158	func fold(dst, part *table) {
159		if part != nil {
160			dst.merge(part)
161		}
162	}
163	
164	// ids returns the message ids held by part, sorted by position.
165	func partIDs(part *table) []string {
166		if part == nil {
167			return nil
168		}
169		var out []string
170		for _, k := range part.orderedKeys() {
171			out = append(out, k.id)
172		}
173		return out
174	}
175	
176	func offOf(t *testing.T, part *table, id string) int64 {
177		t.Helper()
178		if part == nil || part.entries[msgKey{id: id}] == nil {
179			t.Fatalf("message %q not in the part (ids %v)", id, partIDs(part))
180		}
181		return part.entries[msgKey{id: id}].last.off
182	}
